with c as (select id from public.academy_courses where id='meteorology-forecasting-foundations'),
ch as (insert into public.academy_chapters(course_id,title,description,sort_order,published) select id,'المعايير الدولية والحوكمة والتعاون الأرصادي','معايير الرصد وتبادل البيانات والحوكمة والجودة والكفاءات المهنية والخدمات المناخية والتعاون والتطوير المؤسسي.',44,false from c on conflict(course_id,title) do update set description=excluded.description returning id),
u1 as (insert into public.academy_units(chapter_id,title,sort_order,published) select id,'المعايير والممارسات الدولية',1,false from ch on conflict(chapter_id,title) do update set sort_order=excluded.sort_order returning id),
u2 as (insert into public.academy_units(chapter_id,title,sort_order,published) select id,'التعاون والحوكمة والتطوير المؤسسي',2,false from ch on conflict(chapter_id,title) do update set sort_order=excluded.sort_order returning id),
d(slug,title,summary,content,ord,mins,objectives,unit) as (values ('wmo-global-observing-system','النظام العالمي للرصد التابع للمنظمة العالمية للأرصاد','مبادئ تبادل الرصد والتغطية والتكامل العالمي.','{"blocks":[{"type":"text","text":"يعرض الدرس النظام العالمي للرصد التابع للمنظمة العالمية للأرصاد ضمن الحوكمة المؤسسية والممارسات المهنية للخدمات الأرصادية."},{"type":"text","text":"المبدأ الرئيس: مبادئ تبادل الرصد والتغطية والتكامل العالمي. مع مراعاة دور الجهة الوطنية والتزاماتها واحتياجات المستخدمين."},{"type":"text","text":"تحدد الجهات والأدوار والاختصاصات والوثائق المرجعية ذات الصلة قبل تطبيق الإجراء."},{"type":"text","text":"تراجع المصطلحات والمعايير الفنية والإصدارات السارية من الجهات المختصة."},{"type":"text","text":"تترجم المتطلبات إلى إجراءات تشغيلية ومسؤوليات وسجلات يمكن التحقق منها."},{"type":"text","text":"تحدد مؤشرات قياس الامتثال والجودة والاستمرارية ومستوى الخدمة."},{"type":"text","text":"تراعى موثوقية البيانات وشفافية المصدر وحماية المعلومات واستدامة البنية التحتية."},{"type":"text","text":"تراجع الفجوات بين الوضع القائم والممارسة المستهدفة مع ترتيب الأولويات حسب الأثر والمخاطر."},{"type":"text","text":"تحتاج مبادرات التطوير إلى خطة تنفيذ وموارد ومسؤوليات ومواعيد ومؤشرات متابعة."},{"type":"text","text":"تراجع النتائج دورياً وتحدث الإجراءات عند تغير المعايير أو التقنية أو احتياجات المستخدمين."},{"type":"text","text":"مثال تطبيقي: إعداد سجل امتثال يربط كل متطلب بالوثيقة والإجراء والمسؤول ودليل التنفيذ ومؤشر المراجعة."},{"type":"callout","text":"الخلاصة: قوة المرفق الوطني تقوم على العلم والمعايير والحوكمة والكوادر والتعاون والتحسين المستمر."}]}',5160,55,'["تحديد المرجعيات والأدوار المؤسسية","تحويل المتطلبات إلى إجراءات قابلة للتدقيق","بناء مؤشرات متابعة وتحسين"]','المعايير والممارسات الدولية'),
('wmo-global-telecommunication-system','نظام الاتصالات العالمي للأرصاد','تبادل البيانات والرسائل بين المراكز الوطنية.','{"blocks":[{"type":"text","text":"يعرض الدرس نظام الاتصالات العالمي للأرصاد ضمن الحوكمة المؤسسية والممارسات المهنية للخدمات الأرصادية."},{"type":"text","text":"المبدأ الرئيس: تبادل البيانات والرسائل بين المراكز الوطنية. مع مراعاة دور الجهة الوطنية والتزاماتها واحتياجات المستخدمين."},{"type":"text","text":"تحدد الجهات والأدوار والاختصاصات والوثائق المرجعية ذات الصلة قبل تطبيق الإجراء."},{"type":"text","text":"تراجع المصطلحات والمعايير الفنية والإصدارات السارية من الجهات المختصة."},{"type":"text","text":"تترجم المتطلبات إلى إجراءات تشغيلية ومسؤوليات وسجلات يمكن التحقق منها."},{"type":"text","text":"تحدد مؤشرات قياس الامتثال والجودة والاستمرارية ومستوى الخدمة."},{"type":"text","text":"تراعى موثوقية البيانات وشفافية المصدر وحماية المعلومات واستدامة البنية التحتية."},{"type":"text","text":"تراجع الفجوات بين الوضع القائم والممارسة المستهدفة مع ترتيب الأولويات حسب الأثر والمخاطر."},{"type":"text","text":"تحتاج مبادرات التطوير إلى خطة تنفيذ وموارد ومسؤوليات ومواعيد ومؤشرات متابعة."},{"type":"text","text":"تراجع النتائج دورياً وتحدث الإجراءات عند تغير المعايير أو التقنية أو احتياجات المستخدمين."},{"type":"text","text":"مثال تطبيقي: إعداد سجل امتثال يربط كل متطلب بالوثيقة والإجراء والمسؤول ودليل التنفيذ ومؤشر المراجعة."},{"type":"callout","text":"الخلاصة: قوة المرفق الوطني تقوم على العلم والمعايير والحوكمة والكوادر والتعاون والتحسين المستمر."}]}',5170,55,'["تحديد المرجعيات والأدوار المؤسسية","تحويل المتطلبات إلى إجراءات قابلة للتدقيق","بناء مؤشرات متابعة وتحسين"]','المعايير والممارسات الدولية'),
