('national-meteorological-service-assessment','التقييم المؤسسي الشامل لمرفق الأرصاد الوطني','تقييم الامتثال والنضج وخارطة التطوير.','{"blocks":[{"type":"text","text":"يعرض الدرس التقييم المؤسسي الشامل لمرفق الأرصاد الوطني ضمن الحوكمة المؤسسية والممارسات المهنية للخدمات الأرصادية."},{"type":"text","text":"المبدأ الرئيس: تقييم الامتثال والنضج وخارطة التطوير. مع مراعاة دور الجهة الوطنية والتزاماتها واحتياجات المستخدمين."},{"type":"text","text":"تحدد الجهات والأدوار والاختصاصات والوثائق المرجعية ذات الصلة قبل تطبيق الإجراء."},{"type":"text","text":"تراجع المصطلحات والمعايير الفنية والإصدارات السارية من الجهات المختصة."},{"type":"text","text":"تترجم المتطلبات إلى إجراءات تشغيلية ومسؤوليات وسجلات يمكن التحقق منها."},{"type":"text","text":"تحدد مؤشرات قياس الامتثال والجودة والاستمرارية ومستوى الخدمة."},{"type":"text","text":"تراعى موثوقية البيانات وشفافية المصدر وحماية المعلومات واستدامة البنية التحتية."},{"type":"text","text":"تراجع الفجوات بين الوضع القائم والممارسة المستهدفة مع ترتيب الأولويات حسب الأثر والمخاطر."},{"type":"text","text":"تحتاج مبادرات التطوير إلى خطة تنفيذ وموارد ومسؤوليات ومواعيد ومؤشرات متابعة."},{"type":"text","text":"تراجع النتائج دورياً وتحدث الإجراءات عند تغير المعايير أو التقنية أو احتياجات المستخدمين."},{"type":"text","text":"مثال تطبيقي: إعداد سجل امتثال يربط كل متطلب بالوثيقة والإجراء والمسؤول ودليل التنفيذ ومؤشر المراجعة."},{"type":"callout","text":"الخلاصة: قوة المرفق الوطني تقوم على العلم والمعايير والحوكمة والكوادر والتعاون والتحسين المستمر."}]}',5350,55,'["تحديد المرجعيات والأدوار المؤسسية","تحويل المتطلبات إلى إجراءات قابلة للتدقيق","بناء مؤشرات متابعة وتحسين"]','التعاون والحوكمة والتطوير المؤسسي'))
insert into public.academy_lessons(course_id,chapter_id,unit_id,slug,title,summary,content,published,sort_order,level,estimated_minutes,learning_objectives,chapter_title,unit_title)
select c.id,ch.id,case d.unit when 'المعايير والممارسات الدولية' then u1.id else u2.id end,d.slug,d.title,d.summary,d.content::jsonb,false,d.ord,'advanced',d.mins,d.objectives::jsonb,'المعايير الدولية والحوكمة والتعاون الأرصادي',d.unit from d cross join c cross join ch cross join u1 cross join u2
on conflict(course_id,slug) do update set chapter_id=excluded.chapter_id,unit_id=excluded.unit_id,title=excluded.title,summary=excluded.summary,content=excluded.content,published=false,sort_order=excluded.sort_order,level=excluded.level,estimated_minutes=excluded.estimated_minutes,learning_objectives=excluded.learning_objectives,chapter_title=excluded.chapter_title,unit_title=excluded.unit_title;